import{c as a,Q as e,j as l,m as d}from"./chunks/framework.DOi4mjdC.js";const M=JSON.parse('{"title":"GetMMConfig","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetMMConfig","slug":"getmmconfig"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetMMConfig.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetMMConfig.md"}'),r={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/GetMMConfig.md"};function s(n,t,i,o,u,h){return e(),l("div",null,[...t[0]||(t[0]=[d(`<h1 id="getmmconfig" tabindex="-1">GetMMConfig <a class="header-anchor" href="#getmmconfig" aria-label="Permalink to &quot;GetMMConfig&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>灵活的自定义Matmul模板参数配置。通过设置<a href="#table17837129144319">MatmulConfigMode</a>、<a href="#table16317184295116">MatmulShapeParams</a>、<a href="#table8313111211573">MatmulQuantParams</a>、<a href="#table15129204644">MatmulBatchParams</a>、<a href="#table66217141862">MatmulFuncParams</a>，获取自定义的<a href="./MatmulConfig.html#table1761013213153">MatmulConfig</a>。</p><p>MatmulConfigMode指定了获取并要修改的MatmulConfig模板，各模板介绍请参考<a href="./MatmulConfig.html#table6981133810309">模板特性</a>；用户根据使用需求通过设置可变参数，即一个或多个任意顺序的MatmulShapeParams、MatmulQuantParams、MatmulBatchParams、MatmulFuncParams，修改该MatmulConfig模板的相应参数配置。相比<a href="./GetNormalConfig.html">GetNormalConfig</a>、<a href="./GetMDLConfig.html">GetMDLConfig</a>等获取模板的接口，该接口提供了更灵活的自定义Matmul模板参数的配置方式。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;MatmulConfigMode configMode, typename... ArgTypes&gt;</span></span>
<span class="line"><span>__aicore__ inline constexpr MatmulConfig GetMMConfig(ArgTypes&amp;&amp;... args)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>configMode</td><td>获取的MatmulConfig模板。</td></tr><tr><td>ArgTypes</td><td>可变模板参数。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>args</td><td>输入</td><td>可变参数，任意顺序传入需要设置的MatmulShapeParams、MatmulQuantParams、MatmulBatchParams、MatmulFuncParams中的一个或多个。</td></tr></tbody></table><p><strong>表 3</strong> MatmulConfigMode参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>CONFIG_NORM</td><td>表示设置MatmulConfig默认值为Norm模板</td></tr><tr><td>CONFIG_MDL</td><td>表示设置MatmulConfig默认值为MDL模板</td></tr><tr><td>CONFIG_SPECIALMDL</td><td>表示设置MatmulConfig默认值为SpecialMDL模板</td></tr><tr><td>CONFIG_IBSHARE</td><td>表示设置MatmulConfig默认值为IBShare模板</td></tr></tbody></table><p><strong>表 4</strong> MatmulShapeParams参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>singleCoreM</td><td>uint32_t</td><td>单核内M轴shape大小，以元素为单位。</td></tr><tr><td>singleCoreN</td><td>uint32_t</td><td>单核内N轴shape大小，以元素为单位。</td></tr><tr><td>singleCoreK</td><td>uint32_t</td><td>单核内K轴shape大小，以元素为单位。</td></tr><tr><td>basicM</td><td>uint32_t</td><td>与TCubeTiling结构体中的baseM参数含义相同，Matmul计算时base块M轴长度，以元素为单位。</td></tr><tr><td>basicN</td><td>uint32_t</td><td>与TCubeTiling结构体中的baseN参数含义相同，Matmul计算时base块N轴长度，以元素为单位。</td></tr><tr><td>basicK</td><td>uint32_t</td><td>与TCubeTiling结构体中的baseK参数含义相同，Matmul计算时base块K轴长度，以元素为单位。</td></tr></tbody></table><p><strong>表 5</strong> MatmulQuantParams参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>isPerTensor</td><td>bool</td><td>A矩阵half类型输入且B矩阵int8_t类型输入场景，使能B矩阵量化时是否为per tensor。 true：per tensor量化。false：per channel量化。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr><tr><td>hasAntiQuantOffset</td><td>bool</td><td>A矩阵half类型输入且B矩阵int8_t类型输入场景，使能B矩阵量化时是否使用offset系数。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr></tbody></table><p><strong>表 6</strong> MatmulBatchParams参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>isNBatch</td><td>bool</td><td>是否多Batch输入多Batch输出。仅对BatchMatmul有效，使能该参数后，仅支持Norm模板，且需调用IterateNBatch实现多Batch输入多Batch输出。参数取值如下： false：不使能多Batch（默认值）。true：使能多Batch。</td></tr><tr><td>batchMode</td><td>BatchMode</td><td>BatchMatmul场景中Layout类型为NORMAL时，设置BatchMatmul输入A/B矩阵的多batch数据总和与L1 Buffer的大小关系。参数取值如下： BatchMode::BATCH_LESS_THAN_L1：多batch数据总和&lt;L1 Buffer Size；BatchMode::BATCH_LARGE_THAN_L1：多batch数据总和&gt;L1 Buffer Size；BatchMode::SINGLE_LARGE_THAN_L1：单batch数据总和&gt;L1 Buffer Size。</td></tr><tr><td>isBiasBatch</td><td>bool</td><td>批量多Batch的Matmul场景，即BatchMatmul场景，Bias的大小是否带有Batch轴。参数取值如下： true：Bias带有Batch轴，Bias大小为Batch * N（默认值）。 false：Bias不带Batch轴，Bias大小为N，多Batch计算Matmul时，会复用Bias。 注意：BatchMode::SINGLE_LARGE_THAN_L1场景仅支持设置为true。 除MxMatmul场景外，Ascend 950PR/Ascend 950DT支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。 Atlas 推理系列产品AI Core不支持设置为false。 Atlas 200I/500 A2 推理产品不支持设置为false。 Kirin X90支持此参数。</td></tr><tr><td>bmmOutMode</td><td>BatchOutMode</td><td>预留参数。</td></tr></tbody></table><p><strong>表 7</strong> MatmulFuncParams参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>数据类型</th><th>说明</th></tr></thead><tbody><tr><td>intrinsicsLimit</td><td>bool</td><td>当左矩阵或右矩阵在单核上内轴（即尾轴）大于等于65535（元素个数）时，是否使能循环执行数据从Global Memory到L1 Buffer的搬入。例如，左矩阵A[M, K]，单核上的内轴数据singleCoreK大于65535，配置该参数为true后，API内部通过循环执行数据的搬入。参数取值如下： false：当左矩阵或右矩阵在单核上内轴大于等于65535时，不使能循环执行数据的搬入（默认值）。true：当左矩阵或右矩阵在单核上内轴大于等于65535时，使能循环执行数据的搬入。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr><tr><td>enVecND2NZ</td><td>bool</td><td>使能通过vector指令进行ND2NZ。使能时需要设置SetLocalWorkspace。参数取值如下： false：不使能通过vector指令进行ND2NZ（默认值）。true：使能通过vector指令进行ND2NZ。 针对Atlas 推理系列产品AI Core，在Unified Buffer空间足够的条件下（Unified Buffer空间大于2倍TCubeTiling的transLength参数），建议优先使能该参数，搬运性能更好。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</td></tr><tr><td>enableDoubleCache</td><td>bool</td><td>开启IBShare模板后，在L1 Buffer上是否同时缓存两块数据。参数取值如下： false：L1 Buffer上同时缓存一块数据（默认值）。true：使能L1 Buffer上同时缓存两块数据。 注意：该参数取值为true时，需要控制基本块大小，防止两块数据的缓存超过L1 Buffer大小限制。 包括MxMatmul场景，Ascend 950PR/Ascend 950DT不支持此参数。 Kirin X90不支持此参数。</td></tr><tr><td>enableL1CacheUB</td><td>bool</td><td>是否使能L1 Buffer缓存Unified Buffer计算块。建议在MTE3和MTE2流水串行较多的场景使用。参数取值如下： true：使能L1 Buffer缓存Unified Buffer计算块。false：不使能L1 Buffer缓存Unified Buffer计算块。 若要使能L1 Buffer缓存Unified Buffer计算块，必须在Tiling实现中调用SetMatmulConfigParams接口将参数enableL1CacheUBIn设置为true。 包括MxMatmul场景，Ascend 950PR/Ascend 950DT不支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品不支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持该参数。 Atlas 推理系列产品AI Core支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90不支持该参数。</td></tr><tr><td>doMTE2Preload</td><td>uint32_t</td><td>在MTE2流水间隙较大，且M/N数值较大时可通过该参数开启对应M/N方向的预加载功能，开启后能减小MTE2间隙，提升性能。预加载功能仅在MDL模板有效（不支持SpecialMDL模板）。参数取值如下： 0：不开启（默认值）。1：开启M方向preload。2：开启N方向preload。 注意：开启M/N方向的预加载功能时需保证K全载且M/N方向开启DoubleBuffer；其中，M方向的K全载条件为：singleCoreK/baseK &lt;= stepKa；N方向的K全载条件为：singleCoreK/baseK &lt;= stepKb。</td></tr><tr><td>iterateOrder</td><td>IterateOrder</td><td>Matmul做矩阵运算的循环迭代顺序，与表1中的iterateOrder参数含义相同。当ScheduleType参数取值为ScheduleType::OUTER_PRODUCT时，本参数生效。参数取值如下： ORDER_M：先往M轴方向偏移再往N轴方向偏移。 ORDER_N：先往N轴方向偏移再往M轴方向偏移。 UNDEF：当前无效。 注：Norm模板的Matmul场景、MDL模板使用时，若IterateOrder取值ORDER_M，TCubeTiling结构中的stepN需要大于1，IterateOrder取值ORDER_N时，TCubeTiling结构中的stepM需要大于1。MxMatmul仅支持MDL模板。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。 Atlas 推理系列产品AI Core不支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90支持该参数。</td></tr><tr><td>scheduleType</td><td>ScheduleType</td><td>配置Matmul数据搬运模式。参数取值如下： ScheduleType::INNER_PRODUCT：默认模式，在K方向上做MTE1的循环搬运；ScheduleType::OUTER_PRODUCT：在M或N方向上做MTE1的循环搬运；使能后，需要与IterateOrder参数配合使用。 该配置当前只在BatchMatmul场景（使能Norm模板）或 Matmul场景（使能MDL模板或Norm模板）生效。若IterateOrder取值ORDER_M，则N方向循环搬运（在singleCoreN大于baseN场景可能有性能提升），即B矩阵的MTE1搬运并行；若IterateOrder取值ORDER_N，则M方向循环搬运（在singleCoreM大于baseM场景可能有性能提升），即A矩阵的MTE1搬运并行；不能同时使能M方向和N方向循环搬运； 注： Norm模板的Batch Matmul场景或者MDL模板中，singleCoreK&gt;baseK时，不能使能ScheduleType::OUTER_PRODUCT取值，需使用默认模式。Norm模板或MDL模板的Matmul场景，仅支持在纯Cube模式（只有矩阵计算）下配置ScheduleType::OUTER_PRODUCT。MDL模板仅在调用IterateAll计算的场景支持配置ScheduleType::OUTER_PRODUCT。仅在C矩阵输出至GM时，支持配置ScheduleType::OUTER_PRODUCT。 Ascend 950PR/Ascend 950DT支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。 Atlas 推理系列产品AI Core不支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90支持该参数。</td></tr><tr><td>enableReuse</td><td>bool</td><td>SetSelfDefineData函数设置的回调函数中的dataPtr是否直接传递计算数据。若未调用SetSelfDefineData设置dataPtr，该参数仅支持默认值true。参数取值如下： true：直接传递计算数据，仅限单个值。false：传递GM上存储的数据地址信息。 对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持该参数。</td></tr><tr><td>enableUBReuse</td><td>bool</td><td>是否使能Unified Buffer复用。在Unified Buffer空间足够的条件下（Unified Buffer空间大于4倍TCubeTiling的transLength参数），使能该参数后，Unified Buffer空间分为互不重叠的两份，分别存储Matmul计算相邻前后两轮迭代的数据，后一轮迭代数据的搬入将不必等待前一轮迭代的Unified Buffer空间释放，从而优化流水。参数取值如下： true：使能Unified Buffer复用。false：不使能Unified Buffer复用。 包括MxMatmul场景，Ascend 950PR/Ascend 950DT不支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品不支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持该参数。 Atlas 推理系列产品AI Core支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90不支持该参数。</td></tr><tr><td>isPartialOutput</td><td>bool</td><td>是否开启PartialOutput功能，即控制Matmul顺序输出K方向的基本块计算方式：Matmul一次Iterate计算的K轴是否进行累加计算。参数取值如下： true：开启PartialOutput功能，一次Iterate的K轴不进行累加计算，Matmul每次计算输出局部baseK的baseM * baseN大小的矩阵分片。false：不开启PartialOutput功能，一次Iterate的K轴进行累加计算，Matmul每次计算输出SingleCoreK长度的baseM * baseN大小的矩阵分片。 Ascend 950PR/Ascend 950DT支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。 Atlas 推理系列产品AI Core不支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90支持此参数。</td></tr><tr><td>isA2B2Shared</td><td>bool</td><td>是否开启A2和B2的全局管理，即控制所有Matmul对象是否共用A2和B2的double buffer机制。该配置为全局配置，所有Matmul对象取值必须保持一致。注意，开启时，A矩阵、B矩阵的基本块大小均不能超过32KB。 参数取值如下： true：开启。false：关闭（默认值）。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。 Atlas 推理系列产品AI Core不支持该参数。 除MxMatmul场景外，Ascend 950PR/Ascend 950DT支持该参数。 该参数取值为true时，建议同时设置enUnitFlag参数为true，使搬运与计算流水并行，提高性能。 Kirin X90支持此参数。</td></tr><tr><td>isEnableChannelSplit</td><td>bool</td><td>是否使能channel_split功能。正常情况下，Matmul计算出的CubeFormat::NZ格式的C矩阵分形为16<em>16，假设此时的分形个数为x，channel_split功能是使获得的C矩阵分形为16</em>8，同时分形个数变为2x。注意，当前仅在Matmul计算结果C矩阵的Format为CubeFormat::NZ，TYPE为float类型，矩阵乘结果CO1为float类型，输出到Global Memory的场景，支持使能该参数。参数取值如下： false：默认值，不使能channel_split功能，输出的分形为16<em>16。true：使能channel_split功能，输出的分形为16</em>8。 Ascend 950PR/Ascend 950DT支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。 Atlas 推理系列产品AI Core不支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90不支持此参数。</td></tr><tr><td>enableKdimReorderLoad</td><td>bool</td><td>是否使能K轴错峰加载数据。基于相同Tiling参数，执行Matmul计算时，如果多核的左矩阵或者右矩阵相同，且存储于Global Memory，多个核一般会同时访问相同地址以加载矩阵数据，引发同地址访问冲突，影响性能。使能该参数后，多核执行Matmul时，将尽量在相同时间访问矩阵的不同Global Memory地址，减少地址访问冲突概率，提升性能。该参数功能只支持MDL模板，建议K轴较大且左矩阵和右矩阵均非全载场景使能参数。参数取值如下。 false：默认值，关闭K轴错峰加载数据的功能。true：开启K轴错峰加载数据的功能。 除MxMatmul场景外，Ascend 950PR/Ascend 950DT支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。 Atlas 推理系列产品AI Core不支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90支持此参数。</td></tr><tr><td>enableL1BankConflictOptimise</td><td>bool</td><td>是否使能L1上的Bank冲突优化。在Tiling侧调用EnableL1BankConflictOptimise接口获取能否使能该参数的结果，并与TilingKey机制配合使用，在Kernel侧增加代码实现分支。若使能该参数，基于相同Tiling参数执行Matmul计算时，对A、B矩阵和MxMatmul场景的ScaleA、ScaleB矩阵不再连续分配L1 Buffer的空间，在DoubleBuffer场景下，并行计算的数据分别被分配在L1 Buffer的上半部空间和下半部空间，非DoubleBuf场景，数据被分配在L1 Buffer的上半部空间；另外，Bias被分配在L1 Buffer的上半部空间，向量的量化/反量化场景的量化系数被分配在L1 Buffer的下半部空间。参数取值如下。 false：默认值，关闭L1 Bank冲突优化。true：开启L1 Bank冲突优化。 除MxMatmul场景外，Ascend 950PR/Ascend 950DT支持该参数。 Atlas A3 训练系列产品/Atlas A3 推理系列产品不支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持该参数。 Atlas 推理系列产品AI Core不支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。 Kirin X90不支持此参数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p><a href="./MatmulConfig.html#table1761013213153">MatmulConfig结构体</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 获取MatmulConfig模板为Norm模板</span></span>
<span class="line"><span>constexpr static MatmulConfigMode configMode = MatmulConfigMode::CONFIG_NORM;</span></span>
<span class="line"><span>// singleCoreM、singleCoreN、singleCoreK、basicM、basicN、basicK</span></span>
<span class="line"><span>constexpr static MatmulShapeParams shapeParams = {128, 128, 128, 64, 64, 64};</span></span>
<span class="line"><span>// B矩阵量化时为per channel且不使用offset系数</span></span>
<span class="line"><span>constexpr static MatmulQuantParams quantParams = {false, false};</span></span>
<span class="line"><span>// 不使能多Batch</span></span>
<span class="line"><span>constexpr static MatmulBatchParams batchParams{false};</span></span>
<span class="line"><span>// 不进行芯片指令搬运地址偏移量校验，使能通过vector进行ND2NZ</span></span>
<span class="line"><span>constexpr static MatmulFuncParams funcParams{false, true};</span></span>
<span class="line"><span>constexpr static MatmulConfig mmConfig = GetMMConfig&lt;configMode&gt;(shapeParams, quantParams, batchParams, funcParams);</span></span></code></pre></div>`,29)])])}const c=a(r,[["render",s]]);export{M as __pageData,c as default};
